library(haven,dplyr,tidyr,purrr,labelled,readr)
wave1<-read_delim('data/input/wave_one_lsype_young_person_2020.tab',delim='\t')
wave4<-read_delim('data/input/wave_four_lsype_young_person_2020.tab',delim='\t')
ns8_main<-read_delim('data/input/ns8_2015_main_interview.tab',delim='\t')
ns8_derived<-read_delim('data/input/ns8_2015_derived.tab',delim='\t')
ns9_main<-read_delim('data/input/ns9_2022_main_interview.tab',delim='\t')
ns9_derived<-read_delim('data/input/ns9_2022_derived_variables.tab',delim='\t')
all_data<-wave1%>%full_join(wave4,by='NSID')%>%full_join(ns8_main,by='NSID')%>%full_join(ns8_derived,by='NSID')%>%full_join(ns9_main,by='NSID')%>%full_join(ns9_derived,by='NSID')
all_data<-all_data%>%mutate(educ25=case_when(is.na(W8DHANVQH)~-3,W8DHANVQH==-1~-1,W8DHANVQH==-9~-9,W8DHANVQH==-8~-8,TRUE~W8DHANVQH))%>%mutate(educ25=factor(educ25,levels=c(-3,-1,-9,-8,0,1,2,3,4,5,95,96),labels=c('Not asked at fieldwork stage','Not applicable','Refused','Insufficient information','NVQ Entry Level','NVQ Level 1','NVQ Level 2','NVQ Level 3','NVQ Level 4','NVQ Level 5','Other academic qualification','None of these qualifications')))
all_data<-all_data%>%mutate(educ32_num=ifelse(is.na(W9DANVQH)|W9DANVQH%c(-1,-8,-9,-3),NA_real_,W9DANVQH),educ32_num2=ifelse(is.na(W9DVNVQH)|W9DVNVQH%c(-1,-8,-9,-3),NA_real_,W9DVNVQH),educ32_num=pmax(educ32_num,educ32_num2,na.rm=TRUE))%>%mutate(educ32=factor(educ32_num,levels=c(-3,-1,-8,-9,0,1,2,3,4,5,95,96),labels=c('Not asked at fieldwork stage','Not applicable','Missing information','Refused','NVQ Entry Level','NVQ Level 1','NVQ Level 2','NVQ Level 3','NVQ Level 4','NVQ Level 5','Other academic qualification','None of these qualifications')))
for(v in c('W9ACQU0A','W9ACQU0B','W9ACQU0C','W9ACQU0D','W9ACQU0E','W9ACQU0F','W9ACQU0G','W9ACQU0H','W9ACQU0I','W9ACQU0J','W9ACQU0K','W9ACQU0L','W9ACQU0M','W9ACQU0N','W9ACQU0O','W9ACQU0P','W9ACQU0Q','W9ACQU0R','W9ACQU0S')){all_data<-all_data%>%mutate(!!paste0('educadtl32_'):=case_when(!!sym(v)==1~1,!!sym(v)==2~0,TRUE~-3))}
for(v in c('W9VCQU0A','W9VCQU0B','W9VCQU0C','W9VCQU0D','W9VCQU0E','W9VCQU0F','W9VCQU0G','W9VCQU0H','W9VCQU0I','W9VCQU0J','W9VCQU0K','W9VCQU0L','W9VCQU0M','W9VCQU0N','W9VCQU0O','W9VCQU0P','W9VCQU0Q','W9VCQU0R','W9VCQU0S','W9VCQU0T','W9VCQU0U','W9VCQU0V','W9VCQU0W','W9VCQU0X','W9VCQU0Y','W9VCQU0Z','W9VCQUAA','W9VCQUAB','W9VCQUAC','W9VCQUAD','W9VCQUAE','W9VCQUAF','W9VCQUAG','W9VCQUAH','W9VCQUAI')){all_data<-all_data%>%mutate(!!paste0('educvdtl32_'):=case_when(!!sym(v)==1~1,!!sym(v)==2~0,TRUE~-3))}
write_csv(select(all_data,NSID,educ25,educ32,educadtl32,W9ACQU0A_dtl,W9ACQU0B_dtl,W9ACQU0C_dtl,W9ACQU0D_dtl,W9ACQU0E_dtl,W9ACQU0F_dtl,W9ACQU0G_dtl,W9ACQU0H_dtl,W9ACQU0I_dtl,W9ACQU0J_dtl,W9ACQU0K_dtl,W9ACQU0L_dtl,W9ACQU0M_dtl,W9ACQU0N_dtl,W9ACQU0O_dtl,W9ACQU0P_dtl,W9ACQU0Q_dtl,W9ACQU0R_dtl,W9ACQU0S_dtl,educvdtl32,W9VCQU0A_dtl,W9VCQU0B_dtl,W9VCQU0C_dtl,W9VCQU0D_dtl,W9VCQU0E_dtl,W9VCQU0F_dtl,W9VCQU0G_dtl,W9VCQU0H_dtl,W9VCQU0I_dtl,W9VCQU0J_dtl,W9VCQU0K_dtl,W9VCQU0L_dtl,W9VCQU0M_dtl,W9VCQU0N_dtl,W9VCQU0O_dtl,W9VCQU0P_dtl,W9VCQU0Q_dtl,W9VCQU0R_dtl,W9VCQU0S_dtl,W9VCQU0T_dtl,W9VCQU0U_dtl,W9VCQU0V_dtl,W9VCQU0W_dtl,W9VCQU0X_dtl,W9VCQU0Y_dtl,W9VCQU0Z_dtl,W9VCQUAA_dtl,W9VCQUAB_dtl,W9VCQUAC_dtl,W9VCQUAD_dtl,W9VCQUAE_dtl,W9VCQUAF_dtl,W9VCQUAG_dtl,W9VCQUAH_dtl,W9VCQUAI_dtl),'data/output/cleaned_data.csv')